import inspect
from rich.repr import rich_repr

class AlwaysTrueEq:
    def __eq__(self, other):
        return True
    def __repr__(self):
        return "AlwaysTrueEq()"

@rich_repr
class MyClass:
    def __init__(self, a=AlwaysTrueEq()):
        self.a = a

def test_rich_repr_with_custom_eq():
    obj = MyClass()
    # We want to see what auto_rich_repr yields.
    # Since rich_repr adds __rich_repr__ to the class, we can call it.
    results = list(obj.__rich_repr__())
    print(f"Results: {results}")

    # If the bug exists:
    # param.default == param.empty is True (because AlwaysTrueEq() == Parameter.empty is True)
    # It yields getattr(self, 'a'), which is AlwaysTrueEq().
    # results = [AlwaysTrueEq()]

    # If the bug is fixed:
    # param.default is param.empty is False
    # It yields ('a', getattr(self, 'a'), AlwaysTrueEq())
    # results = [('a', AlwaysTrueEq(), AlwaysTrueEq())]

    if len(results) == 1 and isinstance(results[0], tuple):
        print("FIXED: Correctly identified default value")
    elif len(results) == 1 and not isinstance(results[0], tuple):
        print("BUG: Incorrectly identified default value as empty")
    else:
        print(f"Unexpected results: {results}")

if __name__ == "__main__":
    test_rich_repr_with_custom_eq()

