def test_prompt_base_directly():
    from rich.prompt import PromptBase, InvalidResponse

    class TestPrompt(PromptBase[str]):
        pass

    # Case sensitive = True
    p_sensitive = TestPrompt(choices=["Paul", "Jessica"], case_sensitive=True)
    try:
        p_sensitive.process_response("paul")
        print("FAILED: 'paul' should be invalid when case_sensitive=True")
